1	// Drives the app through its screens, binding only to data-testid (AGENTS.md §2). Every test
2	// arranges its own data with these helpers and asserts through them or through data-testid
3	// directly. An action helper returns what the screen reported: an id when a row was created,
4	// true/false for whether the action went through or the screen refused it (its error element
5	// appeared). It throws when neither a result nor an error shows within the wait, so a screen that
6	// does nothing fails the test instead of passing as "refused".
7	import { expect, type Browser, type Locator, type Page } from '@playwright/test';
8	import { existsSync, readFileSync } from 'node:fs';
9	
10	const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
11	const WAIT = 8000;
12	const ERROR_GRACE = 500;      // how long an error left over from the action before may linger
13	const AUDIT_WAIT = 3000;      // how long an audit line may lag the screen
14	
15	const editing = new WeakMap<Page, string>();
16	
17	export function sheetId(): string {
18	  return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
19	}
20	
21	/** The id a creating helper returned; throws when the screen refused (null) so the failure
22	 *  lands on the arranging line rather than on a later assertion. */
23	export function must(id: string | null): string {
24	  if (id === null) throw new Error('the screen refused this action (its error element appeared)');
25	  return id;
26	}
27	
28	function escapeRe(s: string): string {
29	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
30	}
31	
32	/** The trimmed text of a locator, read without waiting: '' when it is not on the page. A poll
33	 *  must never use an auto-waiting read (textContent, getAttribute) on an element that may be
34	 *  re-rendered or removed while it polls; that read would block until the test's own timeout. */
35	async function shown(loc: Locator): Promise<string> {
36	  return ((await loc.allTextContents())[0] ?? '').trim();
37	}
38	
39	/** The ids carried by every element matching `loc`, read without waiting. */
40	async function ids(loc: Locator, prefix: string): Promise<string[]> {
41	  const out: string[] = [];
42	  for (const h of await loc.elementHandles()) out.push(idOf(await h.getAttribute('data-testid'), prefix));
43	  return out;
44	}
45	
46	function idOf(testid: string | null, prefix: string): string {
47	  if (!testid || !testid.startsWith(prefix)) throw new Error(`no ${prefix}* id on ${testid}`);
48	  return testid.slice(prefix.length);
49	}
50	
51	/** Poll until `done` holds (true) or `error` is visible (false); throw when neither happens.
52	 *  Each check returns as soon as it can. An error already visible at the first look after the
53	 *  click may be left over from the action before (the screen clears it when a new action is
54	 *  submitted, see README): it counts as this action's refusal once it has gone away and been
55	 *  shown again, once its text changes, or once ERROR_GRACE has passed with no result. */
56	async function until(page: Page, done: () => Promise<boolean>, error: Locator, what: string): Promise<boolean> {
57	  const deadline = Date.now() + WAIT;
58	  let stale: string | null | undefined;   // text of an error visible at the first look; null if none
59	  let seenGone = false;
60	  const grace = Date.now() + ERROR_GRACE;
61	  while (Date.now() < deadline) {
62	    if (await done()) return true;
63	    const visible = await error.isVisible().catch(() => false);
64	    if (stale === undefined) stale = visible ? await shown(error) : null;
65	    if (visible) {
66	      if (stale === null || seenGone || (await shown(error)) !== stale || Date.now() >= grace) return false;
67	    } else {
68	      seenGone = true;
69	    }
70	    await page.waitForTimeout(50);
71	  }
72	  if (await done()) return true;
73	  if (await error.isVisible().catch(() => false)) return false;
74	  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
75	}
76	
77	async function sleep(ms: number): Promise<void> {
78	  await new Promise((r) => setTimeout(r, ms));
79	}
80	
81	/** A counter the screen shows after a bulk action: the number in the cell once it is visible. */
82	async function counter(page: Page, cell: Locator, error: Locator, what: string): Promise<number | null> {
83	  const ok = await until(page, async () => (await cell.count()) > 0 && (await shown(cell)) !== '', error, what);
84	  return ok ? Number(await shown(cell)) : null;
85	}
86	
87	// ---- session ---------------------------------------------------------------------------------
88	
89	export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
90	  const page = await (await browser.newContext()).newPage();
91	  await page.goto('/');
92	  await page.getByTestId('signin-name').fill(user);
93	  await page.getByTestId('signin-submit').click();
94	  await expect(page.getByTestId('current-user')).toHaveText(user);
95	  await loadSheet(page, sheet);
96	  return page;
97	}
98	
99	export async function loadSheet(page: Page, sheet: string): Promise<void> {
100	  await page.getByTestId('sheet-id-input').fill(sheet);
101	  await page.getByTestId('sheet-load').click();
102	  await expect(page.getByTestId('sheet-current-id')).toHaveText(sheet);
103	}
104	
105	/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
106	 *  again is not observable (the current id already reads that), so the screen first loads a
107	 *  throwaway id, which must change the current id, then the sheet again; it is back once every
108	 *  person row from before is on screen with at least as many claims as before. The show-retired
109	 *  box and the as-of date, which belong to the screen, are put back if the loads reset them. */
110	export async function refresh(page: Page): Promise<void> {
111	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
112	  const before = new Map<string, number>();
113	  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
114	  const retired = page.getByTestId('show-retired');
115	  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
116	  const asofWas = await shown(page.getByTestId('sheet-asof'));
117	  await loadSheet(page, sheet + '-reload');
118	  await loadSheet(page, sheet);
119	  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
120	  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
121	  await expect.poll(async () => {
122	    for (const [id, n] of before) {
123	      const r = row(page, id);
124	      if ((await r.count()) === 0 || (await claimRows(r).count()) < n) return false;
125	    }
126	    return true;
127	  }, { message: 'the sheet is back on screen after a reload', timeout: WAIT }).toBe(true);
128	}
129	
130	export async function setToday(page: Page, date: string): Promise<void> {
131	  await page.getByTestId('sheet-today-input').fill(date);
132	  await page.getByTestId('sheet-today-save').click();
133	  await expect(page.getByTestId('sheet-today')).toHaveText(date);
134	}
135	
136	/** Change the sheet's today where the screen may refuse it (an archived sheet, a viewer, an
137	 *  as-of view): true when the date took, false when the sheet's error element appeared. */
138	export async function setTodayTry(page: Page, date: string): Promise<boolean> {
139	  await page.getByTestId('sheet-today-input').fill(date);
140	  await page.getByTestId('sheet-today-save').click();
141	  return until(page, async () => (await shown(page.getByTestId('sheet-today'))) === date,
142	    page.getByTestId('sheet-error'), 'set today');
143	}
144	
145	/** Archive the sheet: true once the screen shows it archived, false when refused. */
146	export async function archive(page: Page): Promise<boolean> {
147	  await page.getByTestId('sheet-archive').click();
148	  return until(page, async () => (await shown(page.getByTestId('sheet-archived'))) === 'yes',
149	    page.getByTestId('sheet-error'), 'archive');
150	}
151	
152	/** Show the sheet as of a date (this user's screen only). */
153	export async function setAsOf(page: Page, date: string): Promise<void> {
154	  await page.getByTestId('asof-date').fill(date);
155	  await page.getByTestId('asof-set').click();
156	  await expect(page.getByTestId('sheet-asof')).toHaveText(date);
157	}
158	
159	export async function clearAsOf(page: Page): Promise<void> {
160	  await page.getByTestId('asof-clear').click();
161	  await expect(page.getByTestId('sheet-asof')).toHaveText('');
162	}
163	
164	// ---- people ----------------------------------------------------------------------------------
165	
166	export function row(page: Page, personId: string): Locator {
167	  return page.getByTestId(`person-row-${personId}`);
168	}
169	
170	function rows(page: Page): Locator {
171	  return page.locator('[data-testid^="person-row-"]');
172	}
173	
174	function rowsNamed(page: Page, name: string): Locator {
175	  const re = new RegExp(`^\\s*${escapeRe(name.trim())}\\s*$`, 'i');
176	  return rows(page).filter({ has: page.getByTestId('person-name').filter({ hasText: re }) });
177	}
178	
179	/** The id of the (newest) person row showing this name. */
180	export async function personId(page: Page, name: string): Promise<string> {
181	  const r = rowsNamed(page, name).last();
182	  await expect(r).toBeVisible();
183	  return idOf(await r.getAttribute('data-testid'), 'person-row-');
184	}
185	
186	type PersonFields = { name?: string; grade?: string; gradeFrom?: string; terms?: string };
187	
188	async function fillPersonForm(page: Page, f: PersonFields) {
189	  if (f.name !== undefined) await page.getByTestId('person-form-name').fill(f.name);
190	  if (f.grade !== undefined) await page.getByTestId('person-form-grade').selectOption(f.grade);
191	  if (f.gradeFrom !== undefined) await page.getByTestId('person-form-grade-from').fill(f.gradeFrom);
192	  if (f.terms !== undefined) await page.getByTestId('person-form-terms').fill(f.terms);
193	}
194	
195	/** Add a person through the form. The new row's id, or null when the form refused. */
196	export async function addPerson(page: Page, f: PersonFields & { name: string; grade: string }): Promise<string | null> {
197	  const before = await ids(rows(page), 'person-row-');
198	  await fillPersonForm(page, f);
199	  await page.getByTestId('person-form-submit').click();
200	  const ok = await until(page, async () => (await rows(page).count()) > before.length,
201	    page.getByTestId('person-form-error'), 'add person');
202	  if (!ok) return null;
203	  const fresh = (await ids(rows(page), 'person-row-')).filter((id) => !before.includes(id));
204	  return fresh.length === 1 ? fresh[0] : personId(page, f.name);
205	}
206	
207	export async function editOpen(page: Page, personId: string): Promise<void> {
208	  await page.getByTestId(`person-edit-${personId}`).click();
209	  await expect(page.getByTestId('person-form-name')).not.toHaveValue('');
210	  editing.set(page, personId);
211	}
212	
213	/**
214	 * Save the open editor with these changes; true when saved, false when the form refused. `shows` is
215	 * the grade the row shows once saved: by default the grade entered, but a grade dated from another
216	 * day may leave the grade in force on the sheet's today unchanged.
217	 */
218	export async function editSave(page: Page, f: PersonFields, shows: string | undefined = f.grade): Promise<boolean> {
219	  const id = editing.get(page);
220	  if (!id) throw new Error('editSave without editOpen');
221	  await fillPersonForm(page, f);
222	  await page.getByTestId('person-form-submit').click();
223	  const r = row(page, id);
224	  return until(page, async () => {
