643	    page.getByTestId('role-form-error'), 'set role');
644	}
645	
646	/** Delegate the steward role: true once a delegation line appeared. */
647	export async function delegate(page: Page, f: { user: string; from: string; to: string }): Promise<boolean> {
648	  const lines = page.getByTestId('delegate-line');
649	  const was = await lines.count();
650	  await page.getByTestId('delegate-user').fill(f.user);
651	  await page.getByTestId('delegate-from').fill(f.from);
652	  await page.getByTestId('delegate-to').fill(f.to);
653	  await page.getByTestId('delegate-submit').click();
654	  return until(page, async () => (await lines.count()) > was, page.getByTestId('delegate-error'), 'delegate');
655	}
656	
657	export async function exportCsv(page: Page): Promise<string> {
658	  const [download] = await Promise.all([page.waitForEvent('download'), page.getByTestId('export-people').click()]);
659	  const path = await download.path();
660	  if (!path) throw new Error('export produced no file');
661	  return readFileSync(path, 'utf8');
662	}
663	
664	// ---- audit -----------------------------------------------------------------------------------
665	
666	/** The audit lines written for this sheet, in file order. */
667	export function auditFor(sheet: string): string[] {
668	  if (!existsSync(AUDIT_FILE)) return [];
669	  return readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.includes(` sheet=${sheet} `));
670	}
671	
672	/** The sheet's audit lines are exactly these, in order; a line may carry further fields after
673	 *  the expected ones (a later feature may extend a line, never change or reorder its fields).
674	 *  A line may land a moment after the screen shows its result, so the file is re-read until
675	 *  it has as many lines as expected (lines are only ever appended), for AUDIT_WAIT at most. */
676	export async function expectAudit(sheet: string, expected: string[]): Promise<void> {
677	  let lines = auditFor(sheet);
678	  const deadline = Date.now() + AUDIT_WAIT;
679	  while (lines.length < expected.length && Date.now() < deadline) {
680	    await sleep(50);
681	    lines = auditFor(sheet);
682	  }
683	  expect(lines.length, `audit lines for ${sheet}:\n${lines.join('\n')}`).toBe(expected.length);
684	  lines.forEach((line, i) => {
685	    const e = expected[i];
686	    const ok = line === e || line.startsWith(e + ' ');
687	    expect(ok, `audit line ${i + 1}\n  expected: ${e}\n  actual:   ${line}`).toBe(true);
688	  });
689	}
