  }

  protected reset(): void {
    this.editingId.set(null);
    this.form.reset(
      { amount: '', date: this.session.today() ?? '', note: '', corrects: '' },
      { emitEvent: false },
    );
    this.formError.set(null);
  }

  protected submit(): void {
