50	/** A claim starts as DRAFT, is opened and then settled; one a clerk settles above the clerk limit is PENDING
51	 * until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT, OPEN or PENDING claim can be voided. */
52	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
53	
54	/** The status changes a person can ask for on a claim; a rejection also needs a reason. */
55	export type ClaimAction = 'open' | 'settle' | 'approve' | 'void';
56	
57	/** Whether a claim is still open: OPEN, or PENDING a steward. */
58	export function isOpen(claim: Claim): boolean {
59	  return claim.status === 'OPEN' || claim.status === 'PENDING';
60	}
61	
62	/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
63	export function counts(claim: Claim): boolean {
64	  return isOpen(claim) || claim.status === 'SETTLED';
65	}
66	
67	/** Whether a claim goes by the figure its person's last statement bound it to: a PENDING claim is not bound, but
68	 * shows its live figure. */
69	export function bound(claim: Claim): boolean {
70	  return claim.stated && claim.status !== 'PENDING';
71	}
72	
73	/** What a claim's late charge goes by: the sheet's today and its late percent in force on a claim's date; and
74	 * the policy date its rounding goes by, the sheet's today when there is none. */
75	export interface Lateness {
76	  today: string | null;
77	  /** The late percent in force on a date, with two decimals, e.g. "10.00". */
78	  latePct: (date: string) => string;
79	  policyDate: string | null;
80	}
81	
82	/** The date a claim's rounding goes by: a correction's is the date of the claim of its person's (`claims`) it
83	 * corrects, any other's its own. */
84	export function roundsBy(claim: Claim, claims: readonly Claim[]): string {
85	  if (claim.corrects === null) return claim.date;
86	  return claims.find((c) => c.number === claim.corrects)?.date ?? claim.date;
87	}
88	
89	/** Whether a claim's live figures round half up: the date they go by is before the policy date. Otherwise
90	 * they round half to even. */
91	function roundsHalfUp(date: string, late: Lateness): boolean {
92	  return late.policyDate !== null && date < late.policyDate;
93	}
94	
95	/** The days in each period an overdue claim gains the late percent for. */
96	const LATE_PERIOD_DAYS = 30;
97	
98	/** A settled claim's due is the figure it was settled at (its late charge frozen in); a claim bound by its
99	 * person's last statement (and not PENDING) has the figure it was bound to; any other has the figure due at the rate `grade`, the
100	 * one its person has on the claim's date, has now in force on that date, and at least the sheet's floor in force on that date (n/a
101	 * when there is no rate). An overdue claim's due adds its late charge to its figure. Live figures round by the
102	 * date `roundsBy` (see {@link roundsBy}). */
103	export function claimDue(
104	  claim: Claim,
105	  rates: readonly Rate[],
106	  grade: Grade | undefined,
107	  floor: (date: string) => string,
108	  late: Lateness,
109	  roundsBy: string = claim.date,
110	): string {
111	  if (claim.due !== null) return claim.due;
112	  const halfUp = roundsHalfUp(roundsBy, late);
113	  const figure = bound(claim)
114	    ? (claim.statedDue ?? NO_RATE)
115	    : correctionFloored(claim, dueOf(claim.amount, grade && rateOn(rates, grade, claim.date), halfUp), floor(claim.date));
116	  if (figure === NO_RATE) return figure;
117	  return sumAmounts([figure, lateCharge(claim, figure, late, halfUp)]);
118	}
119	
120	/** A due raised to the sheet's floor, except a correction's, which has no floor. */
121	function correctionFloored(claim: Claim, due: string, floor: string): string {
122	  return isCorrection(claim) ? due : floored(due, floor);
123	}
124	
125	/** The late charge on an overdue claim: the late percent in force on its date of its figure for every full 30 days it is overdue,
126	 * rounded like a due; never bound by a statement, it follows the sheet's today. A correction has none. */
127	function lateCharge(claim: Claim, figure: string, late: Lateness, halfUp: boolean): string {
128	  if (isCorrection(claim) || !isOverdue(claim, late.today) || late.today === null) return '0.00';
129	  const days = (Date.parse(late.today) - Date.parse(claim.dueBy)) / 86_400_000;
130	  const periods = Math.floor(days / LATE_PERIOD_DAYS);
131	  return dueOf(figure, timesPct(late.latePct(claim.date), periods), halfUp);
132	}
133	
134	/** A percent with two decimals times a whole number, with two decimals. */
135	function timesPct(pct: string, times: number): string {
136	  const [whole, frac = ''] = pct.split('.');
137	  const hundredths = (BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'))) * BigInt(times);
138	  return `${hundredths / 100n}.${String(hundredths % 100n).padStart(2, '0')}`;
139	}
140	
141	/** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
142	export function isOverdue(claim: Claim, today: string | null): boolean {
143	  return isOpen(claim) && today !== null && claim.dueBy < today;
144	}
145	
146	export interface ClaimForm {
147	  amount: string;
148	  /** Null for the sheet's today. */
149	  date: string | null;
150	  note: string;
