234	  constructor() {
235	    this.form.valueChanges.subscribe(() => this.formError.set(null));
236	    // A new claim is dated the sheet's today unless another date is picked.
237	    effect(() => {
238	      const today = this.session.today() ?? '';
239	      untracked(() => {
240	        if (this.editingId() === null && !this.form.controls.date.dirty) {
241	          this.form.controls.date.setValue(today, { emitEvent: false });
242	        }
243	      });
244	    });
245	  }
246	
247	  /** A settled claim shows the due it was settled at; any other is due at the rate the grade its person has on
248	   * the claim's date has now in force on that date, and at least the sheet's floor, plus its late charge when
249	   * overdue. */
250	  protected due(claim: Claim): string {
251	    return claimDue(claim, this.rates(), gradeOn(this.grades(), claim.date), this.floor.on(), this.late(),
252	      roundsBy(claim, this.claims()));
253	  }
254	
255	  /** Whether the claim is OPEN or PENDING and its due-by is before the sheet's today. */
256	  protected overdue(claim: Claim): boolean {
257	    return isOverdue(claim, this.session.today());
258	  }
259	
260	  /** The name of the period the claim's date falls in; empty when it falls in none. */
261	  protected periodName(claim: Claim): string {
262	    return periodOf(this.periods(), claim.date)?.name ?? '';
263	  }
264	
265	  protected changeStatus(claim: Claim, action: ClaimAction): void {
266	    this.claimError.set(null);
267	    const sheetId = this.session.sheetId();
268	    if (!sheetId) return;
269	    this.api.changeStatus(sheetId, claim.id, action).subscribe({
270	      next: (c) => {
271	        if (this.session.sheetId() === sheetId) this.saved.emit(c);
272	      },
273	      error: (e: HttpErrorResponse) =>
274	        this.claimError.set({
275	          id: claim.id,
276	          message:
277	            e.status === 403
278	              ? `You opened that claim, so someone else must ${action === 'approve' ? 'approve' : 'settle'} it.`
279	              : e.status === 422
280	              ? 'Only a steward can approve a pending claim.'
281	              : e.status === 409 && action === 'approve'
282	              ? 'Only a pending claim can be approved.'
283	              : e.status === 423
284	              ? 'That claim is dated in a closed period.'
285	              : e.status === 409
286	              ? 'That claim\'s status does not allow that change.'
287	              : e.status === 404
288	                ? 'That claim is no longer on this sheet.'
289	                : 'Could not change that claim\'s status.',
290	        }),
291	    });
292	  }
293	
294	  /** Re-settle a SETTLED claim at the figure it would have today as an open claim bound by no statement. */
295	  protected resettle(claim: Claim): void {
296	    this.claimError.set(null);
297	    const sheetId = this.session.sheetId();
298	    if (!sheetId) return;
299	    this.api.resettle(sheetId, claim.id).subscribe({
300	      next: (c) => {
301	        if (this.session.sheetId() === sheetId) this.saved.emit(c);
302	      },
303	      error: (e: HttpErrorResponse) =>
304	        this.claimError.set({
305	          id: claim.id,
306	          message:
307	            e.status === 422
308	              ? 'Only a steward can re-settle a claim.'
309	              : e.status === 423
310	              ? 'That claim is dated in a closed period.'
311	              : e.status === 409
312	              ? 'Only a settled claim can be re-settled.'
313	              : e.status === 404
314	                ? 'That claim is no longer on this sheet.'
315	                : 'Could not re-settle that claim.',
316	        }),
317	    });
318	  }
319	
320	  protected reassignChange(id: number, personId: string): void {
321	    if (this.claimError()?.id === id) this.claimError.set(null);
322	    this.reassignTo.update((m) => {
323	      const next = new Map(m);
324	      if (personId === '') next.delete(id);
325	      else next.set(id, Number(personId));
326	      return next;
327	    });
328	  }
329	
330	  /** Move a claim to the person picked on its row; it keeps its number and date but is live again. */
331	  protected reassign(claim: Claim): void {
332	    this.claimError.set(null);
333	    const sheetId = this.session.sheetId();
334	    if (!sheetId) return;
335	    const personId = this.reassignTo().get(claim.id);
336	    if (personId === undefined) {
337	      this.claimError.set({ id: claim.id, message: 'Pick the person to move that claim to.' });
338	      return;
339	    }
340	    this.api.reassign(sheetId, claim.id, personId).subscribe({
341	      next: (c) => {
342	        this.reassignTo.update((m) => {
343	          const next = new Map(m);
344	          next.delete(claim.id);
345	          return next;
346	        });
347	        if (this.session.sheetId() === sheetId) this.saved.emit(c);
348	      },
349	      error: (e: HttpErrorResponse) =>
350	        this.claimError.set({
351	          id: claim.id,
352	          message:
353	            e.status === 422
354	              ? 'Only a steward can move a claim.'
355	              : e.status === 423
356	              ? 'That claim is dated in a closed period.'
357	              : e.status === 409
358	              ? 'Only a draft, open or pending claim can be moved, and never a correction.'
359	              : e.status === 410
360	              ? 'That person is retired before the claim\'s date.'
361	              : e.status === 400
362	              ? 'Pick another person to move that claim to.'
363	              : e.status === 404
364	                ? 'That claim or person is no longer on this sheet.'
365	                : 'Could not move that claim.',
366	        }),
367	    });
368	  }
369	
370	  protected reasonChange(id: number, reason: string): void {
371	    if (this.claimError()?.id === id) this.claimError.set(null);
372	    this.rejectReasons.update((m) => new Map(m).set(id, reason));
373	  }
374	
375	  /** Reject a PENDING claim with the reason typed on its row: it is OPEN again. */
376	  protected reject(claim: Claim): void {
377	    this.claimError.set(null);
378	    const sheetId = this.session.sheetId();
379	    if (!sheetId) return;
380	    const reason = (this.rejectReasons().get(claim.id) ?? '').trim();
381	    if (reason === '') {
382	      this.claimError.set({ id: claim.id, message: 'Type a reason to reject that claim.' });
383	      return;
384	    }
385	    this.api.reject(sheetId, claim.id, reason).subscribe({
386	      next: (c) => {
387	        this.rejectReasons.update((m) => {
388	          const next = new Map(m);
389	          next.delete(claim.id);
390	          return next;
391	        });
392	        if (this.session.sheetId() === sheetId) this.saved.emit(c);
393	      },
394	      error: (e: HttpErrorResponse) =>
395	        this.claimError.set({
396	          id: claim.id,
397	          message:
398	            e.status === 422
399	              ? 'Only a steward can reject a pending claim.'
400	              : e.status === 423
401	              ? 'That claim is dated in a closed period.'
402	              : e.status === 409
403	              ? 'Only a pending claim can be rejected.'
404	              : e.status === 404
405	                ? 'That claim is no longer on this sheet.'
406	                : e.status === 400
407	                  ? 'Type a reason on one line to reject that claim.'
408	                  : 'Could not reject that claim.',
409	        }),
410	    });
411	  }
412	
413	  protected edit(claim: Claim): void {
414	    this.claimError.set(null);
415	    if (claim.status !== 'DRAFT') {
416	      this.claimError.set({
417	        id: claim.id,
418	        message: 'Only a draft claim can be edited. To change it, void it and add a new one.',
419	      });
420	      return;
421	    }
422	    if (periodOf(this.periods(), claim.date)?.closed) {
423	      this.claimError.set({ id: claim.id, message: 'That claim is dated in a closed period.' });
424	      return;
425	    }
426	    this.editingId.set(claim.id);
427	    this.form.setValue(
428	      { amount: claim.amount, date: claim.date, note: claim.note, corrects: claim.corrects ?? '' },
429	      { emitEvent: false },
430	    );
431	    this.formError.set(null);
432	  }
433	
434	  protected reset(): void {
435	    this.editingId.set(null);
436	    this.form.reset(
437	      { amount: '', date: this.session.today() ?? '', note: '', corrects: '' },
438	      { emitEvent: false },
439	    );
440	    this.formError.set(null);
441	  }
442	
443	  protected submit(): void {
444	    if (this.submitting) return;
445	    this.formError.set(null);
446	    const sheetId = this.session.sheetId();
447	    if (!sheetId) {
448	      this.formError.set('Load a sheet first.');
449	      return;
450	    }
451	    const value = this.form.getRawValue();
452	    const amount = value.amount.trim();
453	    if (!AMOUNT.test(amount)) {
454	      this.formError.set('Type an amount with up to two decimals; a negative one is a correction.');
455	      return;
456	    }
457	    const corrects = value.corrects.trim();
458	    if (corrects !== '' && !NUMBER.test(corrects)) {
459	      this.formError.set('Type the number of the settled claim this corrects.');
460	      return;
461	    }
462	    const form = {
463	      amount,
464	      date: value.date || null,
465	      note: value.note.trim(),
466	      corrects: corrects === '' ? null : corrects,
467	    };
468	    const id = this.editingId();
469	    const request = id === null ? this.api.add(sheetId, this.personId(), form) : this.api.update(sheetId, id, form);
470	    this.submitting = true;
471	    request.subscribe({
472	      next: (c) => {
473	        this.submitting = false;
474	        if (this.session.sheetId() === sheetId) this.saved.emit(c);
475	        this.reset();
476	      },
477	      error: (e: HttpErrorResponse) => {
478	        this.submitting = false;
479	        // A refused new claim is dropped: the form starts afresh, dated the sheet's today, under its error.
480	        if (id === null) this.reset();
481	        this.formError.set(
482	          e.status === 400
483	            ? 'A negative amount is a correction: name the number of a settled claim of this person it corrects.'
484	            : e.status === 404
485	            ? 'That person or claim is no longer on this sheet.'
486	            : e.status === 422
487	              ? 'That claim is dated after its person is retired.'
488	              : e.status === 423
489	              ? 'That claim is dated in a closed period.'
490	              : e.status === 409
491	                ? 'Only a draft claim can be edited. To change it, void it and add a new one.'
492	                : 'Could not save that claim.',
493	        );
494	      },
495	    });
496	  }
497	}
